"""Changes the description of the first revision issue that is not issued yet with ModifyRevisionIssues, then restores it.

Needs a revision issue that is not issued.
"""
import aclib

revisionIssues = aclib.RunTapirCommand ('GetRevisionIssues')['revisionIssues']
openIssues = [issue for issue in revisionIssues if not issue['isIssued']]
if not openIssues:
    raise SystemExit ('No revision issue that is not issued yet.')
revisionIssue = openIssues[0]

# Only the given fields change.
aclib.PrintJson (aclib.RunTapirCommand ('ModifyRevisionIssues', {
    'revisionIssues': [{
        'revisionIssueId': revisionIssue['revisionIssueId'],
        'description': revisionIssue['description'] + ' (Tapir)'
    }]
}))
aclib.RunTapirCommand ('GetRevisionIssues')

aclib.PrintJson (aclib.RunTapirCommand ('ModifyRevisionIssues', {
    'revisionIssues': [{
        'revisionIssueId': revisionIssue['revisionIssueId'],
        'description': revisionIssue['description']
    }]
}))

"""Lists the changes of the last revision of every layout with GetCurrentRevisionChangesOfLayouts.

Needs at least one layout.
"""
import aclib

layouts = aclib.RunTapirCommand ('GetDatabases', {'types': ['Layout']})['databases']
if not layouts:
    raise SystemExit ('No layout in the project.')

aclib.PrintJson (aclib.RunTapirCommand ('GetCurrentRevisionChangesOfLayouts', {
    'layoutDatabaseIds': [{'databaseId': layout['databaseId']} for layout in layouts]
}))

"""Clouds an area with CreateChangeMarkers, creating a new Change for it, and links a second cloud to the same Change.

The markers are placed in the active window (the floor plan story, a section, a detail, a worksheet or a layout).
The Change ID must not exist yet in the project.
"""
import aclib

changeId = 'TAPIR-EX-1'

result = aclib.RunTapirCommand ('CreateChangeMarkers', {
    'changeMarkersData': [
        {
            'polygon': [{'x': 0.0, 'y': 0.0}, {'x': 4.0, 'y': 0.0}, {'x': 4.0, 'y': 3.0}, {'x': 0.0, 'y': 3.0}],
            'markerPosition': {'x': 5.0, 'y': 3.5},
            'changeId': changeId,
            'createChange': True,
            'changeDescription': 'Opening moved'
        },
        {
            'polygon': [{'x': 8.0, 'y': 0.0}, {'x': 10.0, 'y': 0.0}, {'x': 9.0, 'y': 2.0}],
            'markerComponent': 'CloudOnly',
            'changeId': changeId
        }
    ]
})
aclib.PrintJson (result)

aclib.RunTapirCommand ('GetDetailsOfElements', {
    'elements': [element for element in result['elements'] if 'elementId' in element]
})
aclib.RunTapirCommand ('GetRevisionChanges')
